const j=await Bun.file(p).json();
const map=(id,w,h)=>{const n=j.data.nodes.find(x=>x.id===id); if(n)n.layout.size=[w,h];};
map("host-root",375,667); map("hud",375,60); map("game-view",375,375); map("dpad",375,232);
j.id="host-small-draft";
await Bun.write(".beegame/tmp/ui-host-small.json",JSON.stringify(j,null,2));
'; bun .beegame/delivery/check-content.mjs --layout-draft .beegame/tmp/ui-host-small.json 375 667 --game-view game-view --camera .beegame/tmp/camera-draft.json | bun .beegame/tmp/summarize.mjs

bun -e '
const p=".beegame/tmp/ui-host-small.json";
const j=await Bun.file(p).json();
for (const n of j.data.nodes) {
  if (n.parentId==="dpad") n.layout.size=[109,58];
}
await Bun.write(p,JSON.stringify(j,null,2));
'; bun .beegame/delivery/check-content.mjs --layout-draft .beegame/tmp/ui-host-small.json 375 667 --game-view game-view --camera .beegame/tmp/camera-draft.json | bun .beegame/tmp/summarize.mjs
